/**
 * Remembered placement: where a closed panel goes when it reopens. A place stores the docker's id AND its name plus the
 * tab index. Every pure operation that moves or closes a panel records the place in the same step (no exceptions).
 * Resolution on reopen, in order: the docker with the stored id, the docker with the stored name (case-insensitive;
 * the docker may have been removed and recreated, or the ids regenerated by an import), the panel's `home` (a docker
 * name), the screenset's `defaultDocker`, the first docker in depth-first order. Pure, no React.
 */
import {
  dockerByName,
  findDocker,
  treeDockers,
  type Docker,
  type PanelId,
  type Place,
  type Screenset,
} from './tree';

export type PlaceSource = 'id' | 'name' | 'home' | 'default' | 'first' | 'none';

export interface ResolvedPlace {
  docker: Docker | null;
  /** The remembered tab index when resolved by id or name; absent otherwise (join at the end). */
  index?: number;
  via: PlaceSource;
}

/** The screenset with `panel`'s place recorded as tab `index` of `docker`. */
export const recordPlace = (
  s: Screenset,
  panel: PanelId,
  docker: Pick<Docker, 'id' | 'name'>,
  index: number
): Screenset => {
  const prev = s.lastDocker[panel];
  if (prev && prev.docker === docker.id && prev.name === docker.name && prev.index === index) {
    return s;
  }
  const place: Place = { docker: docker.id, name: docker.name, index };
  return { ...s, lastDocker: { ...s.lastDocker, [panel]: place } };
};

/** Where `panel` would reopen (see the file comment). `home` is the panel's home docker name. */
export function resolvePlace(s: Screenset, panel: PanelId, home?: string): ResolvedPlace {
  const place = s.lastDocker[panel];
  if (place) {
    const byId = findDocker(s.tree, place.docker);
    if (byId) {
      return { docker: byId, index: place.index, via: 'id' };
    }
    const byName = dockerByName(s.tree, place.name);
    if (byName) {
      return { docker: byName, index: place.index, via: 'name' };
    }
  }
  if (home) {
    const byHome = dockerByName(s.tree, home);
    if (byHome) {
      return { docker: byHome, via: 'home' };
    }
  }
  if (s.defaultDocker !== undefined) {
    const def = findDocker(s.tree, s.defaultDocker);
    if (def) {
      return { docker: def, via: 'default' };
    }
  }
  const first = treeDockers(s.tree)[0];
  return first ? { docker: first, via: 'first' } : { docker: null, via: 'none' };
}
